// 1. Classic Dangling Pointer (Manual Heap Allocation)
int* ptr = new int(100);

// Use the memory
*ptr = 42;

delete ptr;
// ptr now refers to deallocated memory (Dangling)

// ptr = nullptr; // Mitigation step: Resetting the pointer

// 2. Dangling Pointer via Stack Scope Exit
int* create_dangle() {
    int stack_val = 50;
    // Warning: Returning the address of a local variable
    return &stack_val;
} // stack_val goes out of scope (destroyed)

int* dp = create_dangle();
// *dp access leads to Undefined Behavior

// 3. Preventing Dangling Pointers using RAII/Smart Pointers
// std::unique_ptr ensures automatic memory cleanup
class Resource {};

void safe_function() {
    std::unique_ptr<Resource> safe_ptr(new Resource());
    // Safe usage
} // safe_ptr goes out of scope; Resource memory is freed
  // automatically via delete (no dangle possible)
